mask={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# generate possible 2x2 squares and L trominoes; color L by missing corner
pieces=[]
for r in range(6):
 for c in range(6):
  sq={(r+i,c+j) for i in range(2) for j in range(2)}
  if sq<=mask: pieces.append((sq,1,'sq',r,c))
  for miss,(color,tag) in { (0,0):(2,'missing_UL'),(0,1):(4,'missing_UR'),(1,0):(3,'missing_LL'),(1,1):(5,'missing_LR')}.items():
   shape={(r+i,c+j) for i in range(2) for j in range(2)}-{(r+miss[0],c+miss[1])}
   if shape<=mask: pieces.append((shape,color,tag,r,c))
from collections import Counter
bycell={p:[] for p in mask}
for item in pieces:
 for cell in item[0]: bycell[cell].append(item)
sols=[]
def dfs(rem, used, out):
 if not rem:
  if Counter(x[2] for x in used)['sq']==1 and len(used)==5: sols.append(used.copy())
  return
 cell=min(rem, key=lambda x:sum(p[0]<=rem for p in bycell[x]))
 for p in bycell[cell]:
  if p[0]<=rem:
   dfs(rem-p[0], used+[p],out)
dfs(mask,[],None)
len(sols)
